INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'ROADMAP-1: QNFO.RSCH IDEAS-PUBLIC-GATE-1: The public Ideas list publishes raw prompts and pipeline fragments as threads',
 'QNFO.RSCH; charter pillar research; doer: idea-hub via qnfo-code-orchestrator. Measured 2026-11-04: https://ideas.qnfo.org/ lists a raw role prompt ("TASK WRITER You are one of three independent research writers ...") as a public thread while the page says operational conversations never appear. A scout counted 18 of 20 listed threads defective (prompts, "Re-entry from [redacted]" fragments, a literal &lt;p&gt;, other authors'' arXiv abstracts tagged auto-candidate); this session reproduced the prompt, the redacted fragment and the entity, not the count. Cause: pubQuestion is a denylist (STAMP, TOOLINV, ROLEPROMPT, INTERNAL, OPS, JUNK) without the RESEARCH allowlist that publicTitle applies, and ideasHome publishes every live or ideation item that passes it. Work: (1) make the public list an allowlist: show a thread only when its first user message reads as a research question (interrogative or question mark, 12 to 400 characters, no role or prompt markers) and matches the RESEARCH terms, keeping the denylist; (2) decode and strip HTML entities from titles; (3) add the leaked titles as fixtures in idea-hub/public-gate-batch.test.mjs; (4) name the producers that write prompt-shaped rows into the live source and file them. Carry the tag IDEAS-PUBLIC-GATE-1 in a comment at the edit. Done: the runtime probe passes and the fixtures cover the five leak classes. Failure mode: an allowlist hides a real question, so keep an operator view of hidden rows. Source: docs/BLUE-SKY-ROADMAP-2026-11.md section 4 (PROD-01).' || char(10) || char(10) ||
 'code-task: repo=qnfo-workers path=idea-hub/worker.js' || char(10) ||
 'code-anchor: function pubQuestion(s){const t=clean(s,1000);' || char(10) ||
 'runtime-probe: {"url":"https://ideas.qnfo.org/","status":200,"absent":"TASK WRITER"}' || char(10) ||
 'code-probe: {"paths":["idea-hub/worker.js"],"contains":"IDEAS-PUBLIC-GATE-1"}',
 'session:bluesky-2026-11', 'code', 'high', 'open', unixepoch() * 1000, unixepoch() * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title LIKE 'ROADMAP-1: QNFO.RSCH IDEAS-PUBLIC-GATE-1:%' AND status = 'open');

